using UnityEngine;
using System.Collections.Generic;

public class ProjectilePool : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int prewarmCount;

    private Queue<GameObject> _pool = new Queue<GameObject>();
    private HashSet<GameObject> _inPool = new HashSet<GameObject>();

    private void Awake()
    {
        for (int i = 0; i < prewarmCount; i++)
        {
            CreateNewInstance();
        }
    }

    private GameObject CreateNewInstance()
    {
        GameObject instance = Instantiate(prefab, transform);
        instance.SetActive(false);
        _pool.Enqueue(instance);
        _inPool.Add(instance);
        return instance;
    }

    public GameObject Rent()
    {
        GameObject instance;

        if (_pool.Count > 0)
        {
            instance = _pool.Dequeue();
            _inPool.Remove(instance);
        }
        else
        {
            // Instantiate a new one if the pool is empty
            // We don't add it to _inPool here because it's immediately being "rented"
            // but we need to track it so Return() knows it's valid.
            // Actually, the simplest way is to create it, then treat it as active.
            instance = Instantiate(prefab, transform);
        }

        instance.SetActive(true);
        return instance;
    }

    public void Return(GameObject go)
    {
        if (go == null)
        {
            return;
        }

        // Prevent adding the same object twice
        if (_inPool.Contains(go))
        {
            return;
        }

        go.SetActive(false);
        _pool.Enqueue(go);
        _inPool.Add(go);
    }
}
